#[test]
fn test_pages_do_not_leak() {
    let epages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let words: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let owords: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tlines: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let feats: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let etext: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let refs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    ep_new(epages, 1, 61200, 79200);
    ep_new(epages, 2, 61200, 79200);
    xl_tw(words, etext, feats, 1, 7200, 10000, 10200, 11200, 0, 0, 0, sr_text(), 0, &crate::testport::text_blob("page")[..]);
    xl_tw(words, etext, feats, 2, 7200, 10000, 10200, 11200, 0, 0, 0, sr_text(), 0, &crate::testport::text_blob("next")[..]);
    xl_ow(owords, etext, feats, 1, 7200, 10000, 10200, 11200, 0, 0, 0, &crate::testport::text_blob("page")[..]);
    xl_ow(owords, etext, feats, 2, 7200, 10000, 10200, 11200, 0, 0, 0, &crate::testport::text_blob("mext")[..]);
    crate::testport::assert_eq(xl_align(epages, words, owords, tlines, feats, etext, refs, cg, 1), 1, "page 1: one group");
    crate::testport::assert_eq(cg_get(cg, 0, cgf_sim()), 1000, "page");
    crate::testport::assert_eq(cg_get(cg, 0, 0), 1, "on page 1");
    crate::testport::assert_eq(xl_align(epages, words, owords, tlines, feats, etext, refs, cg, 2), 1, "page 2: one group");
    crate::testport::assert_eq(cg_get(cg, 1, cgf_sim()), 750, "next / mext");
    crate::testport::assert_eq(cg_get(cg, 1, 0), 2, "on page 2");
    crate::testport::assert_eq(xl_align(epages, words, owords, tlines, feats, etext, refs, cg, 3), 0, "page 3: nothing");
    crate::testport::assert_eq(cg_count(cg), 2, "two rows");
    crate::testport::assert_eq(rf_get(refs, cg_get(cg, 1, cgf_tfirst()), 1), 1, "page 2's text word is words row 1");
}
#[test]
fn test_a_line_too_long_for_the_table_is_paired_greedily() {
    let epages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let words: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let owords: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tlines: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let feats: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let etext: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let refs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mut i: i32 = 0;
    ep_new(epages, 1, 100000000, 79200);
    while i < 1100 {
        xl_tw(words, etext, feats, 1, 1000 + (i * 100), 10000, 1060 + (i * 100), 11200, 0, 0, 0, sr_text(), 0, &crate::testport::text_blob("w")[..]);
        xl_ow(owords, etext, feats, 1, 1005 + (i * 100), 10000, 1065 + (i * 100), 11200, 0, 0, 0, &crate::testport::text_blob("w")[..]);
        i += 1;
    }
    crate::testport::assert_eq(xl_align(epages, words, owords, tlines, feats, etext, refs, cg, 1), 1100, "every word is a group");
    crate::testport::assert_eq(cg_get(cg, 1099, cgf_ocount()), 1, "the last has its OCR word");
    crate::testport::assert_eq(xl_ref(cg, refs, 1099, cgf_ofirst(), 0), 1099, "which is the last");
    crate::testport::assert_eq(cg_get(cg, 500, cgf_flags()), 0, "paired");
}
